function formatBytes(bytes: number) { return `${Math.max(0, Math.round(bytes / 1024)).toLocaleString('vi-VN')} KB` }
function formatDate(value: string) { return new Intl.DateTimeFormat('vi-VN', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value)) }
function parseUtcDate(value?: string) { if (!value) return undefined; return new Date(/[zZ]|[+-]\d{2}:?\d{2}$/.test(value) ? value : `${value}Z`) }
function statusColor(status: string) { return status === 'Processed' ? 'success' : status === 'Failed' ? 'error' : status === 'Processing' ? 'processing' : 'default' }
function errorMessage(error: any) {
  const data = error?.response?.data
  const validationErrors = data?.errors ? Object.values(data.errors).flat().join(' ') : ''
  const detail = typeof data?.detail === 'string' ? data.detail : ''
  const technicalDetail = /openai|api key|exception|stack trace|server unavailable|request unavailable/i.test(detail)
  return validationErrors || (!technicalDetail && detail) || 'Tạm thời không thể thực hiện yêu cầu. Vui lòng thử lại sau.'
}

function summarySectionIcon(line: string) {
  const normalized = line.toLowerCase()
  if (normalized.includes('checklist') || normalized.includes('ôn tập') || normalized.includes('review')) return <CheckOutlined />
  if (normalized.includes('định nghĩa') || normalized.includes('definition')) return <BookOutlined />
  if (normalized.includes('khái niệm') || normalized.includes('concept')) return <ThunderboltFilled />
  return <RobotOutlined />
}

function renderSummaryContent(content: string) {
  return content.split(/\r?\n/).map((line, index) => {
    const trimmed = line.trim()
    if (!trimmed) return <div key={index} className="summary-spacer" />
    const cleaned = trimmed
      .replace(/^#{1,4}\s*/, '')
      .replace(/^\s*[-*•]\s+/, '')
      .replace(/^\s*\[[^\]]*\]\s*/, '')
      .replace(/[\[\]*]/g, '')
      .replace(/\s{2,}/g, ' ')
      .trim()
    const heading = cleaned
    if (trimmed.startsWith('#')) return <div key={index} className="summary-section-title"><span>{summarySectionIcon(heading)}</span><Typography.Title level={4}>{heading}</Typography.Title></div>
    if (/^[-*•]\s+/.test(trimmed) || /^\s*\[[^\]]*\]/.test(trimmed)) return <div key={index} className="summary-bullet"><CheckOutlined /><span>{cleaned}</span></div>
    return <div key={index} className="summary-paragraph summary-clean-line"><span className="summary-inline-icon">{summarySectionIcon(cleaned)}</span><Typography.Text>{cleaned}</Typography.Text></div>
  })
}

