function AdminAccountsOnlyPage() {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [selectedUser, setSelectedUser] = useState<AdminUser>()
  const [savingId, setSavingId] = useState<string>()
  const { data: stats } = useQuery({ queryKey: ['admin-stats'], queryFn: () => api.get<AdminStats>('/admin/statistics').then(r => r.data) })
  const { data: users, isLoading } = useQuery({ queryKey: ['admin-users', search], queryFn: () => api.get<PagedResponse<AdminUser>>('/admin/users', { params: { search, page: 1, pageSize: 100 } }).then(r => r.data) })
  const { data: docs } = useQuery({ queryKey: ['admin-account-docs', selectedUser?.id], enabled: Boolean(selectedUser), queryFn: () => api.get<PagedResponse<AdminDocument>>('/admin/documents', { params: { search: selectedUser?.email, page: 1, pageSize: 100 } }).then(r => r.data) })

  async function setPlan(item: AdminUser, plan: string) {
    setSavingId(item.id)
    try { await api.post(`/admin/users/${item.id}/plan`, { plan, durationDays: plan === 'Free' ? null : 30 }); message.success(`Đã cập nhật gói ${plan}.`); queryClient.invalidateQueries({ queryKey: ['admin-users'] }) }
    catch (error) { message.error(errorMessage(error)) }
    finally { setSavingId(undefined) }
  }
  async function setActive(item: AdminUser, active: boolean) {
    try { await api.post(`/admin/users/${item.id}/${active ? 'activate' : 'deactivate'}`); queryClient.invalidateQueries({ queryKey: ['admin-users'] }) }
    catch (error) { message.error(errorMessage(error)) }
  }
  async function setQuota(item: AdminUser, value: number | null) {
    try { await api.post(`/admin/users/${item.id}/quota`, { tokenLimitPerDay: value }); queryClient.invalidateQueries({ queryKey: ['admin-users'] }) }
    catch (error) { message.error(errorMessage(error)) }
  }
  async function deleteUser(item: AdminUser) {
    try { await api.delete(`/admin/users/${item.id}`); message.success(`Đã xóa vĩnh viễn tài khoản ${item.email}.`); setSelectedUser(current => current?.id === item.id ? undefined : current); queryClient.invalidateQueries({ queryKey: ['admin-users'] }); queryClient.invalidateQueries({ queryKey: ['admin-stats'] }) }
    catch (error) { message.error(errorMessage(error)) }
  }
  async function download(item: AdminDocument) {
    try { const response = await api.get(`/admin/documents/${item.id}/download`, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); const anchor = document.createElement('a'); anchor.href = url; anchor.download = item.originalFileName; anchor.click(); URL.revokeObjectURL(url) }
    catch (error) { message.error(errorMessage(error)) }
  }

  return <div className="page admin-subpage">
    <div className="hero-row"><div><Typography.Text className="eyebrow">ADMIN / ACCOUNTS</Typography.Text><Typography.Title level={1}>Quản lý tài khoản</Typography.Title><Typography.Paragraph type="secondary">Điều chỉnh gói, trạng thái hoạt động và quota token trên từng tài khoản.</Typography.Paragraph></div></div>
    <Row gutter={[16, 16]} className="stats-row"><Col xs={12} lg={6}><Card><Statistic title="Người dùng" value={stats?.totalUsers ?? 0} /></Card></Col><Col xs={12} lg={6}><Card><Statistic title="Tài liệu" value={stats?.totalDocuments ?? 0} /></Card></Col><Col xs={12} lg={6}><Card><Statistic title="Dung lượng" value={formatBytes(stats?.storageBytes ?? 0)} /></Card></Col><Col xs={12} lg={6}><Card><Statistic title="AI requests" value={stats?.aiRequestCount ?? 0} /></Card></Col></Row>
    <Card className="content-card account-management-card">
      <Input prefix={<SearchOutlined />} value={search} onChange={event => setSearch(event.target.value)} placeholder="Tìm email hoặc tên..." allowClear className="account-search" />
      <div className="account-table-head"><span>Tài khoản</span><span>Gói</span><span>Hoạt động</span><span>Token / ngày</span><span aria-hidden="true" /></div>
      {isLoading ? <Skeleton active /> : (users?.items ?? []).length === 0 ? <Empty description="Không có tài khoản" /> : <div className="account-table-body">{(users?.items ?? []).map(item => <div className="account-table-row" key={item.id}>
        <div className="account-identity"><Avatar className={`account-avatar plan-avatar-${item.plan.toLowerCase()}`}>{item.firstName[0]}</Avatar><div><Space size={6}><Typography.Text strong>{item.firstName} {item.lastName}</Typography.Text><Tag className={`plan-tag plan-tag-${item.plan.toLowerCase()}`}>{item.plan.toUpperCase()}</Tag></Space><Typography.Text type="secondary" className="account-email">{item.email}</Typography.Text></div></div>
        <Select size="small" className="account-plan-select" value={item.plan} loading={savingId === item.id} options={[{ value: 'Free', label: 'Free' }, { value: 'Plus', label: 'Plus' }, { value: 'Pro', label: 'Pro' }]} onChange={value => void setPlan(item, value)} />
        <div className="account-active-control"><Switch size="small" checked={item.isActive} onChange={value => void setActive(item, value)} /><Tag color={item.isActive ? 'green' : 'red'}>{item.isActive ? 'Đang hoạt động' : 'Đã tắt'}</Tag></div>
        <InputNumber size="small" className="quota-input" min={0} value={item.aiTokenLimitPerDay ?? undefined} placeholder="∞" addonAfter="token" onChange={value => void setQuota(item, value)} />
        <Space size={2} className="account-row-actions"><Button type="text" size="small" icon={<EyeOutlined />} onClick={() => setSelectedUser(item)} aria-label="Xem thông tin tài khoản" /><Popconfirm title="Xóa vĩnh viễn tài khoản này?" description="Tất cả tài liệu và dữ liệu liên quan sẽ bị xóa, không thể khôi phục." okText="Xóa vĩnh viễn" cancelText="Hủy" okButtonProps={{ danger: true }} onConfirm={() => void deleteUser(item)}><Button danger type="text" size="small" icon={<DeleteOutlined />} aria-label="Xóa vĩnh viễn tài khoản" /></Popconfirm></Space>
      </div>)}</div>}
    </Card>
    <Modal title={<Space><EyeOutlined /> Thông tin tài khoản</Space>} open={Boolean(selectedUser)} footer={null} onCancel={() => setSelectedUser(undefined)}>{selectedUser && <><Descriptions bordered column={1} size="small"><Descriptions.Item label="Tài khoản">{selectedUser.email}</Descriptions.Item><Descriptions.Item label="Gói">{selectedUser.plan}</Descriptions.Item><Descriptions.Item label="Trạng thái">{selectedUser.isActive ? 'Đang hoạt động' : 'Đã tắt'}</Descriptions.Item><Descriptions.Item label="Token hôm nay">{selectedUser.aiTokensUsedToday.toLocaleString('vi-VN')} / {selectedUser.aiTokenLimitPerDay?.toLocaleString('vi-VN') ?? 'Không giới hạn'}</Descriptions.Item></Descriptions><Typography.Title level={5} style={{ marginTop: 20 }}>Tài liệu đã tải</Typography.Title><List size="small" dataSource={docs?.items ?? []} locale={{ emptyText: 'Chưa có tài liệu' }} renderItem={item => <List.Item actions={[<Button key="download" type="link" onClick={() => void download(item)}>Tải</Button>]}>{item.originalFileName}</List.Item>} /></>}</Modal>
  </div>
}

