function AdminUsagePage() {
  const { data, isLoading } = useQuery({ queryKey: ['admin-ai-usage-page'], queryFn: () => api.get<AiUsageSummary[]>('/admin/ai-usage').then(r => r.data) })
  function level(tokens: number) { if (tokens > 130000) return { color: 'red', label: 'Rất cao' }; if (tokens >= 100000) return { color: 'volcano', label: 'Cao' }; if (tokens >= 70000) return { color: 'orange', label: 'Khá cao' }; if (tokens >= 50000) return { color: 'gold', label: 'Trung bình cao' }; if (tokens >= 40000) return { color: 'blue', label: 'Trung bình' }; if (tokens >= 20000) return { color: 'cyan', label: 'Thấp' }; return { color: 'green', label: 'An toàn' } }
  return <div className="page admin-subpage"><div className="hero-row"><div><Typography.Text className="eyebrow">ADMIN / AI USAGE</Typography.Text><Typography.Title level={1}>AI usage</Typography.Title><Typography.Paragraph type="secondary">Màu sắc phân cấp theo tổng token: 20k, 40k, 50k, 70k, 100k và trên 130k.</Typography.Paragraph></div></div><Card className="content-card" loading={isLoading}><List dataSource={data ?? []} renderItem={item => { const tokens = item.inputTokens + item.outputTokens; const status = level(tokens); return <List.Item><List.Item.Meta title={item.operation} description={`${item.requestCount} requests`} /><Space><Tag color={status.color}>{status.label}</Tag><Typography.Text strong>{tokens.toLocaleString('vi-VN')} tokens</Typography.Text></Space></List.Item> }} /></Card></div>
}

export function LegacyAdminSupportPage() {
  const queryClient = useQueryClient(); const [reply, setReply] = useState<Record<string, string>>({})
  const { data, isLoading } = useQuery({ queryKey: ['admin-support-page'], queryFn: () => api.get<SupportTicket[]>('/admin/support-tickets').then(r => r.data), refetchInterval: 5000 })
  async function resolve(ticket: SupportTicket) { const value = reply[ticket.id]?.trim(); if (!value) return; try { await api.post(`/admin/support-tickets/${ticket.id}/resolve`, value, { headers: { 'Content-Type': 'application/json' } }); message.success('Đã gửi phản hồi.'); queryClient.invalidateQueries({ queryKey: ['admin-support-page'] }) } catch (error) { message.error(errorMessage(error)) } }
  return <div className="page admin-subpage"><div className="hero-row"><div><Typography.Text className="eyebrow">ADMIN / SUPPORT</Typography.Text><Typography.Title level={1}>Hỗ trợ khách hàng</Typography.Title><Typography.Paragraph type="secondary">Mỗi tin nhắn hiển thị rõ tài khoản gửi để admin trả lời đúng người.</Typography.Paragraph></div></div><Card className="content-card" loading={isLoading}>{(data ?? []).map(ticket => <Card.Grid key={ticket.id} className="support-admin-card"><Space><Avatar size="small">{ticket.userFullName?.[0] ?? 'U'}</Avatar><div><Typography.Text strong>{ticket.userFullName ?? 'Tài khoản'}</Typography.Text><Typography.Text type="secondary" style={{ display: 'block' }}>{ticket.userEmail ?? 'Không có email'}</Typography.Text></div></Space><Typography.Paragraph style={{ marginTop: 14 }}>{ticket.message}</Typography.Paragraph>{ticket.adminReply && <Alert type="success" showIcon message={ticket.adminReply} />}{ticket.status === 'Open' && <Space.Compact block style={{ marginTop: 12 }}><Input value={reply[ticket.id] ?? ''} onChange={event => setReply({ ...reply, [ticket.id]: event.target.value })} placeholder="Nhập phản hồi..." /><Button type="primary" disabled={!reply[ticket.id]?.trim()} onClick={() => void resolve(ticket)}>Gửi</Button></Space.Compact>}</Card.Grid>)}</Card></div>
}

export function LegacyAdminSupportConversationPage() {
  const queryClient = useQueryClient(); const [reply, setReply] = useState<Record<string, string>>({}); const [selectedUserId, setSelectedUserId] = useState<string>()
  const { data, isLoading } = useQuery({ queryKey: ['admin-support-page'], queryFn: () => api.get<SupportTicket[]>('/admin/support-tickets').then(r => r.data), refetchInterval: 5000 })
  const users = Array.from(new Map((data ?? []).filter(ticket => ticket.userId).map(ticket => [ticket.userId!, { id: ticket.userId!, name: ticket.userFullName ?? 'Tài khoản', email: ticket.userEmail ?? '', unread: (data ?? []).filter(item => item.userId === ticket.userId && item.status === 'Open').length }])).values())
  useEffect(() => { if (!selectedUserId && users[0]) setSelectedUserId(users[0].id) }, [selectedUserId, users])
  const selectedTickets = (data ?? []).filter(ticket => ticket.userId === selectedUserId)
  async function markRead(userId: string) { try { await api.post(`/admin/support-users/${userId}/read`); queryClient.invalidateQueries({ queryKey: ['admin-support-page'] }) } catch (error) { message.error(errorMessage(error)) } }
  async function replyTo(ticket: SupportTicket) { const value = reply[ticket.id]?.trim(); if (!value) return; try { await api.post(`/admin/support-tickets/${ticket.id}/resolve`, value, { headers: { 'Content-Type': 'application/json' } }); setReply({ ...reply, [ticket.id]: '' }); message.success('Đã gửi tin nhắn.'); queryClient.invalidateQueries({ queryKey: ['admin-support-page'] }) } catch (error) { message.error(errorMessage(error)) } }
  return <div className="page admin-subpage"><div className="hero-row"><div><Typography.Text className="eyebrow">ADMIN / SUPPORT</Typography.Text><Typography.Title level={1}>Hỗ trợ khách hàng</Typography.Title><Typography.Paragraph type="secondary">Chọn tài khoản để chat. Tin nhắn mới được gom theo người gửi và hiển thị số chưa xem.</Typography.Paragraph></div></div><Row gutter={[16, 16]}><Col xs={24} md={8}><Card className="content-card support-user-list" title="Tài khoản nhắn tin" loading={isLoading}><List dataSource={users} renderItem={item => <List.Item className={selectedUserId === item.id ? 'is-selected' : ''} onClick={() => { setSelectedUserId(item.id); void markRead(item.id) }}><List.Item.Meta avatar={<Badge count={item.unread} size="small"><Avatar>{item.name[0]}</Avatar></Badge>} title={item.name} description={item.email} /></List.Item>} locale={{ emptyText: 'Chưa có tin nhắn' }} /></Card></Col><Col xs={24} md={16}><Card className="content-card support-admin-conversation" title={users.find(item => item.id === selectedUserId)?.name ?? 'Chọn tài khoản'} loading={isLoading}><div className="support-chat-window">{selectedTickets.length === 0 ? <Empty description="Chọn tài khoản để xem cuộc trò chuyện" /> : selectedTickets.slice().reverse().map(ticket => <div key={ticket.id} className="support-thread"><Typography.Text type="secondary" className="support-message-meta">{formatDate(ticket.createdAtUtc)} · {ticket.userEmail}</Typography.Text><div className="support-bubble user">{ticket.message}</div>{ticket.adminReply && <div className="support-bubble assistant">{ticket.adminReply}</div>}<Space.Compact block><Input value={reply[ticket.id] ?? ''} onChange={event => setReply({ ...reply, [ticket.id]: event.target.value })} placeholder="Nhắn tiếp cho tài khoản này..." /><Button type="primary" disabled={!reply[ticket.id]?.trim()} onClick={() => void replyTo(ticket)}>Gửi</Button></Space.Compact></div>)}</div></Card></Col></Row></div>
}

