  const sendSupport = useMutation({ mutationFn: (content: string) => api.post('/support/tickets', { subject: 'Hỗ trợ khách hàng', message: content }), onSuccess: () => { setSupportMessage(''); queryClient.invalidateQueries({ queryKey: ['support-tickets'] }) }, onError: error => message.error(errorMessage(error)) })
