function SupportPage() {
  const queryClient = useQueryClient()
  const [messageText, setMessageText] = useState('')
  const { data: tickets, isLoading } = useQuery({ queryKey: ['support-tickets'], queryFn: () => api.get<SupportTicket[]>('/support/tickets').then(r => r.data), refetchInterval: 5000 })
  const send = useMutation({ mutationFn: (content: string) => api.post('/support/tickets', { subject: 'Hỗ trợ khách hàng', message: content }), onSuccess: () => { setMessageText(''); queryClient.invalidateQueries({ queryKey: ['support-tickets'] }) }, onError: error => message.error(errorMessage(error)) })
  const orderedTickets = [...(tickets ?? [])].sort((a, b) => new Date(a.createdAtUtc).getTime() - new Date(b.createdAtUtc).getTime())
  function renderReplies(value: string, key: string) { return value.split(/\r?\n/).filter(Boolean).map((line, index) => <div key={`${key}-${index}`} className="support-bubble other">{line}</div>) }
  return <div className="support-widget-page"><Card className="support-widget-card" title={<Space><CustomerServiceOutlined /> Hỗ trợ EduMind</Space>} loading={isLoading}><div className="support-widget-messages"><div className="support-bubble other">Xin chào! EduMind đã nhận được tin nhắn của bạn. Admin sẽ cố gắng phản hồi sớm nhất, thường trong vòng 10 phút. Bạn có thể gửi thêm thông tin bất cứ lúc nào.</div>{orderedTickets.map(ticket => <div key={ticket.id} className="support-thread"><div className="support-bubble mine">{ticket.message}</div>{ticket.adminReply && renderReplies(ticket.adminReply, ticket.id)}</div>)}</div><div className="support-chat-input"><Input.TextArea autoSize={{ minRows: 2, maxRows: 5 }} value={messageText} onChange={event => setMessageText(event.target.value)} placeholder="Nhập tin nhắn..." /><Button type="primary" icon={<SendOutlined />} loading={send.isPending} disabled={!messageText.trim()} onClick={() => send.mutate(messageText.trim())}>Gửi</Button></div></Card></div>
}

function CvScorePage() {
  const [documentId, setDocumentId] = useState<string>()
  const [targetRole, setTargetRole] = useState('Backend Developer')
  const [experienceLevel, setExperienceLevel] = useState('Junior')
  const [jobDescription, setJobDescription] = useState('')
  const [score, setScore] = useState<CvScore>()
  const { data, isLoading } = useQuery({ queryKey: ['documents', 'cv-score'], queryFn: () => api.get<PagedResponse<DocumentItem>>('/documents', { params: { page: 1, pageSize: 100 } }).then(r => r.data) })
  const pdfDocuments = (data?.items ?? []).filter(document => document.fileType.toLowerCase() === 'pdf')
  const scoreRequest = useMutation({ mutationFn: () => api.post<CvScore>(`/documents/${documentId}/cv-score`, { targetRole, experienceLevel, jobDescription: jobDescription.trim() || null }).then(r => r.data), onSuccess: result => { setScore(result); message.success('Đã chấm điểm CV.'); }, onError: error => message.error(errorMessage(error)) })
  const milestones = [{ min: 0, label: 'Cần cải thiện', range: '0–49' }, { min: 50, label: 'Cơ bản', range: '50–69' }, { min: 70, label: 'Khá', range: '70–79' }, { min: 80, label: 'Rất tốt', range: '80–89' }, { min: 90, label: 'Xuất sắc', range: '90–100' }]
  const scoreColor = score ? score.totalScore >= 80 ? '#2f7b61' : score.totalScore >= 60 ? '#d08a25' : '#d45d5d' : '#4d7de8'
  return <div className="page cv-score-page"><div className="hero-row"><div><Typography.Text className="eyebrow">AI SUPPORT TOOL · IT RESUME</Typography.Text><Typography.Title level={1}><FilePdfOutlined className="cv-score-title-icon" /> Chấm điểm CV IT</Typography.Title><Typography.Paragraph type="secondary">Chỉ nhận CV PDF ngành công nghệ thông tin. Kết quả dựa trên bằng chứng có trong CV, không phỏng đoán thông tin còn thiếu.</Typography.Paragraph></div></div><Row gutter={[20, 20]} align="stretch"><Col xs={24} lg={9}><Card className="content-card cv-score-form-card"><Typography.Title level={3}>Thiết lập đánh giá</Typography.Title><Typography.Text type="secondary">Chọn CV đã tải lên và vai trò IT mục tiêu.</Typography.Text><div className="cv-score-field"><Typography.Text strong>CV PDF</Typography.Text><Select showSearch optionFilterProp="label" value={documentId} onChange={setDocumentId} loading={isLoading} className="cv-score-select" placeholder="Chọn tài liệu PDF" options={pdfDocuments.map(document => ({ value: document.id, label: document.originalFileName }))} notFoundContent="Chưa có PDF đã xử lý" /></div><div className="cv-score-field"><Typography.Text strong>Vị trí IT mục tiêu</Typography.Text><Select value={targetRole} onChange={setTargetRole} className="cv-score-select" options={['Backend Developer', 'Frontend Developer', 'Full-stack Developer', 'Software Engineer', 'Mobile Developer', 'DevOps Engineer', 'Cloud Engineer', 'Data Analyst', 'Data Engineer', 'AI/ML Engineer', 'QA Engineer', 'Cybersecurity Engineer'].map(value => ({ value, label: value }))} /></div><div className="cv-score-field"><Typography.Text strong>Cấp độ kinh nghiệm</Typography.Text><Select value={experienceLevel} onChange={setExperienceLevel} className="cv-score-select" options={[{ value: 'Intern', label: 'Intern' }, { value: 'Fresher', label: 'Fresher' }, { value: 'Junior', label: 'Junior' }, { value: 'Mid-level', label: 'Mid-level' }, { value: 'Senior', label: 'Senior' }]} /></div><div className="cv-score-field"><Typography.Text strong>Mô tả công việc <Typography.Text type="secondary">(không bắt buộc)</Typography.Text></Typography.Text><Input.TextArea value={jobDescription} onChange={event => setJobDescription(event.target.value)} maxLength={2500} showCount autoSize={{ minRows: 4, maxRows: 7 }} placeholder="Dán JD để có thêm điểm đối chiếu..." /></div><Button type="primary" size="large" block icon={<RobotOutlined />} loading={scoreRequest.isPending} disabled={!documentId || scoreRequest.isPending} onClick={() => scoreRequest.mutate()}>{scoreRequest.isPending ? 'Đang phân tích CV...' : 'Chấm điểm CV'}</Button><Typography.Text type="secondary" className="cv-score-token-note">Bản chấm sử dụng rubric 6 nhóm theo bằng chứng. Cùng CV, vai trò và JD sẽ dùng lại kết quả đã lưu để giữ điểm ổn định.</Typography.Text></Card></Col><Col xs={24} lg={15}>{score ? <div className="cv-score-result"><Card className="content-card cv-score-overview"><div className="cv-score-overview-main"><Progress type="circle" percent={score.totalScore} strokeColor={scoreColor} trailColor="#eaf0f8" format={percent => <><strong>{percent}</strong><small>/100</small></>} /><div><Typography.Text className="eyebrow">KẾT QUẢ ĐÁNH GIÁ</Typography.Text><Typography.Title level={2}>{score.grade}</Typography.Title><Typography.Text type="secondary">{score.fileName} · {score.targetRole} · {score.experienceLevel}</Typography.Text><Typography.Paragraph className="cv-score-summary">{score.summary}</Typography.Paragraph></div></div><div className="cv-score-milestones">{milestones.map(item => <div key={item.range} className={`cv-score-milestone ${score.totalScore >= item.min ? 'is-reached' : ''}`}><span>{item.range}</span><b>{item.label}</b></div>)}</div></Card><Card className="content-card cv-category-card" title="6 nhóm đánh giá theo bằng chứng"><div className="cv-category-list">{score.categories.map(category => <div className="cv-category-row" key={category.name}><div className="cv-category-heading"><Typography.Text strong>{category.name}</Typography.Text><Typography.Text strong>{category.score}/{category.maxScore}</Typography.Text></div><Progress percent={Math.round((category.score / category.maxScore) * 100)} showInfo={false} strokeColor={category.score / category.maxScore >= .7 ? '#4d7de8' : '#d6a344'} /><Typography.Text type="secondary">{category.reason}</Typography.Text></div>)}</div></Card><Row gutter={[16, 16]}><Col xs={24} md={12}><Card className="content-card cv-insight-card" title="Điểm mạnh"><List size="small" dataSource={score.strengths} locale={{ emptyText: 'Chưa có dữ liệu nổi bật' }} renderItem={item => <List.Item><CheckCircleOutlined className="cv-positive-icon" />{item}</List.Item>} /></Card></Col><Col xs={24} md={12}><Card className="content-card cv-insight-card" title="Cần cải thiện"><List size="small" dataSource={score.weaknesses} locale={{ emptyText: 'Chưa có dữ liệu cần lưu ý' }} renderItem={item => <List.Item><CloseCircleOutlined className="cv-negative-icon" />{item}</List.Item>} /></Card></Col></Row><Card className="content-card cv-recommendation-card" title="Gợi ý chỉnh sửa"><List size="small" dataSource={score.recommendations} locale={{ emptyText: 'Chưa có đề xuất' }} renderItem={(item, index) => <List.Item><Tag color="blue">{index + 1}</Tag>{item}</List.Item>} /></Card></div> : <Card className="content-card cv-empty-state"><div className="cv-empty-icon"><FilePdfOutlined /></div><Typography.Title level={3}>Sẵn sàng đọc CV của bạn</Typography.Title><Typography.Paragraph type="secondary">Kết quả sẽ hiển thị điểm tổng, 6 nhóm tiêu chí, bằng chứng, điểm mạnh, điểm yếu và đúng 5 gợi ý chỉnh sửa.</Typography.Paragraph><div className="cv-score-empty-metrics"><span><b>100</b> điểm</span><span><b>6</b> nhóm tiêu chí</span><span><b>PDF</b> bắt buộc</span></div></Card>}</Col></Row></div>
}

function DocumentsPage() {
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [uploading, setUploading] = useState(false)
  const { data, isLoading } = useQuery({ queryKey: ['documents', search], queryFn: () => api.get<PagedResponse<DocumentItem>>('/documents', { params: { search, page: 1, pageSize: 20 } }).then(r => r.data) })

  async function uploadFile(file: File) {
    const form = new FormData(); form.append('file', file); setUploading(true)
    try { await api.post('/documents', form, { headers: { 'Content-Type': 'multipart/form-data' } }); message.success('Đã tải tài liệu. Hệ thống đang xử lý.'); queryClient.invalidateQueries({ queryKey: ['documents'] }) } catch (error) { message.error(errorMessage(error)) } finally { setUploading(false) }
  }

  function remove(id: string) {
    Modal.confirm({ title: 'Xóa tài liệu này?', content: 'Các kết quả AI liên quan cũng sẽ bị xóa.', okText: 'Xóa', okType: 'danger', cancelText: 'Hủy', onOk: async () => { await api.delete(`/documents/${id}`); queryClient.invalidateQueries({ queryKey: ['documents'] }); message.success('Đã xóa tài liệu') } })
  }

  return <div className="page"><div className="hero-row"><div><Typography.Text className="eyebrow">YOUR LIBRARY</Typography.Text><Typography.Title level={1}>Tài liệu của tôi</Typography.Title><Typography.Paragraph type="secondary">Mỗi tài liệu là một bước tiến trong hành trình học tập.</Typography.Paragraph></div><Upload accept=".pdf,.docx,.txt" showUploadList={false} beforeUpload={file => { void uploadFile(file); return false }}><Button type="primary" icon={<CloudUploadOutlined />} size="large" loading={uploading}>Tải tài liệu</Button></Upload></div><Card className="content-card"><Flex gap={12} className="toolbar" wrap><Input prefix={<SearchOutlined />} placeholder="Tìm kiếm tài liệu..." value={search} onChange={event => setSearch(event.target.value)} allowClear /><Select defaultValue="all" options={[{ value: 'all', label: 'Tất cả loại file' }, { value: 'Pdf', label: 'PDF' }, { value: 'Docx', label: 'DOCX' }, { value: 'Txt', label: 'TXT' }]} /></Flex>{isLoading ? <Skeleton active /> : data?.items.length === 0 ? <Empty description="Không tìm thấy tài liệu" /> : <List className="documents-list" dataSource={data?.items} renderItem={doc => <List.Item actions={[<Link key="detail" to={`/documents/${doc.id}`}>Chi tiết</Link>, <Button key="delete" type="text" danger onClick={() => remove(doc.id)}>Xóa</Button>]}><List.Item.Meta avatar={<span className={`file-icon ${doc.fileType.toLowerCase()}`}><FilePdfOutlined /></span>} title={<Link to={`/documents/${doc.id}`}>{doc.originalFileName}</Link>} description={`${formatBytes(doc.fileSizeBytes)} · Tải lên ${formatDate(doc.createdAtUtc)}`} /><Tag color={statusColor(doc.status)}>{doc.status === 'Processed' ? 'Sẵn sàng' : doc.status === 'Processing' ? 'Đang xử lý' : doc.status}</Tag></List.Item>} />}</Card></div>
}

function useChatSessionPersistence(documentId: string, active: string, session: ChatSession | null, setSession: (session: ChatSession | null) => void) {
  const storageKey = 'edumind.active-chat-session'
  useEffect(() => {
    const stored = localStorage.getItem(storageKey)
    if (!stored) return
    try {
      const value = JSON.parse(stored) as { documentId: string; session: ChatSession; expiresAt: number }
      if (value.documentId !== documentId || value.expiresAt <= Date.now()) {
        localStorage.removeItem(storageKey)
        return
      }
      setSession(value.session)
    } catch {
      localStorage.removeItem(storageKey)
    }
  }, [documentId, setSession])

  useEffect(() => {
    if (!session) return
    const save = () => localStorage.setItem(storageKey, JSON.stringify({ documentId, session, expiresAt: Date.now() + 5 * 60 * 1000 }))
    save()
    if (active !== 'chat') {
      const expiryTimer = window.setTimeout(() => {
        localStorage.removeItem(storageKey)
        setSession(null)
      }, 5 * 60 * 1000)
      return () => window.clearTimeout(expiryTimer)
    }
    const timer = window.setInterval(save, 30_000)
    return () => {
      window.clearInterval(timer)
      save()
    }
  }, [active, documentId, session])
}

function DocumentDetailPage() {
  const { id = '' } = useParams(); const location = useLocation(); const queryClient = useQueryClient(); const active = new URLSearchParams(location.search).get('tab') ?? 'summary'; const { user } = useAuth(); const [chatInput, setChatInput] = useState(''); const [session, setSession] = useState<ChatSession | null>(null); const [chatSending, setChatSending] = useState(false); useChatSessionPersistence(id, active, session, setSession)
  const { data: document, isLoading } = useQuery({ queryKey: ['document', id], queryFn: () => api.get<DocumentDetail>(`/documents/${id}`).then(r => r.data) })
  const { data: summary, isLoading: summaryLoading } = useQuery({ queryKey: ['summary', id], queryFn: () => api.get<Summary>(`/documents/${id}/summary`).then(r => r.data), enabled: Boolean(document?.hasSummary) })
  const { data: mindmap } = useQuery({ queryKey: ['mindmap', id], queryFn: () => api.get<MindMap>(`/documents/${id}/mindmap`).then(r => r.data), enabled: Boolean(user?.isPlus && document?.hasMindMap) })
  const { data: flashcards } = useQuery({ queryKey: ['flashcards', id], queryFn: () => api.get<Flashcards>(`/documents/${id}/flashcards`).then(r => r.data), enabled: Boolean(user?.isPlus && document?.flashcardCount) })
  const { data: quiz } = useQuery({ queryKey: ['quiz', id], queryFn: () => api.get<Quiz>(`/documents/${id}/quiz`).then(r => r.data), enabled: Boolean(document?.quizCount) })
  const chatQuery = useQuery({ queryKey: ['chat', session?.id], queryFn: () => api.get<ChatMessage[]>(`/chat/sessions/${session?.id}/messages`).then(r => r.data), enabled: Boolean(session) })
  const generate = useMutation({ mutationFn: (request: { type: string; forceRegenerate?: boolean; questionCount?: number }) => api.post(`/documents/${id}/${request.type}`, { forceRegenerate: request.forceRegenerate ?? false, questionCount: request.questionCount }), onSuccess: (_, request) => { queryClient.invalidateQueries({ queryKey: ['document', id] }); queryClient.invalidateQueries({ queryKey: [request.type, id] }); message.success(`Đã tạo ${request.type}`) }, onError: error => message.error(errorMessage(error)) })

  useEffect(() => { if (document?.status === 'Processing') { const timer = setInterval(() => queryClient.invalidateQueries({ queryKey: ['document', id] }), 2500); return () => clearInterval(timer) } }, [document?.status, id, queryClient])
  async function sendChat() { if (!chatInput.trim() || chatSending) return; setChatSending(true); try { let current = session; if (!current) { const result = await api.post<ChatSession>(`/documents/${id}/chat/sessions`, { title: 'Trao đổi về tài liệu' }); current = result.data; setSession(current) } await api.post(`/chat/sessions/${current.id}/messages`, { content: chatInput }); setChatInput(''); await chatQuery.refetch() } catch (error) { message.error(errorMessage(error)) } finally { setChatSending(false) } }
  if (isLoading) return <div className="page"><Skeleton active /></div>
  if (!document) return <div className="page"><Alert type="error" message="Không tìm thấy tài liệu" /></div>

  const activePanel = !user?.isPlus && (active === 'mindmap' || active === 'flashcards') ? <Card className="plus-locked-panel"><LockOutlined /><Typography.Title level={3}>Tính năng Plus</Typography.Title><Typography.Paragraph>Mind Map và Flashcards chỉ dành cho tài khoản Plus hoặc Pro.</Typography.Paragraph><Link to="/preferences/plans"><Button type="primary">Nâng cấp gói</Button></Link></Card> : active === 'mindmap' ? <MindMapPanel data={mindmap} loading={generate.isPending} onGenerate={() => generate.mutate({ type: 'mindmap' })} /> : active === 'flashcards' ? <FlashcardsPanel data={flashcards} loading={generate.isPending} onGenerate={() => generate.mutate({ type: 'flashcards' })} /> : active === 'quiz' ? <QuizPanel data={quiz} isPlus={Boolean(user?.isPlus)} loading={generate.isPending} onGenerate={(questionCount) => generate.mutate({ type: 'quiz', forceRegenerate: true, questionCount })} /> : active === 'chat' ? <ChatPanel messages={chatQuery.data ?? []} value={chatInput} sending={chatSending} onChange={setChatInput} onSend={() => void sendChat()} /> : <SummaryPanel summary={summary} loading={summaryLoading} generating={generate.isPending} onGenerate={() => generate.mutate({ type: 'summary' })} />
  return <div className="page detail-page"><Link to="/documents" className="back-link">← Quay lại thư viện</Link><div className="detail-heading"><div><Tag color="blue">{document.fileType}</Tag><Typography.Title level={1}>{document.originalFileName}</Typography.Title><Typography.Text type="secondary">{formatBytes(document.fileSizeBytes)} · {formatDate(document.createdAtUtc)}</Typography.Text></div><Space><Tag color={statusColor(document.status)}>{document.status === 'Processed' ? 'Sẵn sàng' : document.status}</Tag><Button href={`${import.meta.env.VITE_API_URL ?? 'http://127.0.0.1:5194/api'}/documents/${id}/download`} target="_blank">Tải xuống</Button></Space></div>{document.processingError && <Alert type="error" showIcon message={document.processingError} />}{document.status !== 'Processed' && <Alert className="processing-alert" type="info" showIcon message="AI features sẽ sẵn sàng sau khi tài liệu được xử lý." description="Bạn có thể rời trang, hệ thống sẽ cập nhật trạng thái tự động." />}{document.status === 'Processed' && <Card className="detail-tool-card content-card"><div className="detail-tool-header"><div><Typography.Text className="eyebrow">SELECTED AI TOOL</Typography.Text><Typography.Title level={3}><span className="detail-tool-header-icon">{SIDEBAR_TOOLS.find(item => item.key === active)?.icon ?? '✦'}</span>{SIDEBAR_TOOLS.find(item => item.key === active)?.label ?? 'Tóm tắt'}</Typography.Title></div><Tag color="blue">Đang phân tích riêng tài liệu này</Tag></div>{activePanel}</Card>}</div>
}

function EmptyAi({ title, description, action, loading = false }: { title: string; description: string; action: () => void; loading?: boolean }) { return <div className="ai-empty"><div className="ai-empty-icon">✦</div><Typography.Title level={3}>{title}</Typography.Title><Typography.Paragraph type="secondary">{description}</Typography.Paragraph><Button type="primary" loading={loading} onClick={action}>Tạo bằng AI</Button></div> }
function SummaryPanel({ summary, loading, generating, onGenerate }: { summary?: Summary; loading: boolean; generating: boolean; onGenerate: () => void }) { if (loading) return <div className="ai-loading"><Spin size="large" tip="Đang tải bản tóm tắt..." /></div>; if (!summary) return <EmptyAi title="Chưa có bản tóm tắt" description="AI sẽ chắt lọc các ý chính, định nghĩa và checklist ôn tập cho bạn." action={onGenerate} loading={generating} />; return <Spin spinning={generating} tip="AI đang tạo lại bản tóm tắt..."><div className="summary-content"><div className="summary-reading-header"><div className="summary-reading-icon"><RobotOutlined /></div><div><Typography.Text className="eyebrow">AI STUDY NOTES</Typography.Text><Typography.Title level={3}>Bản tóm tắt dễ đọc</Typography.Title><Typography.Text type="secondary">Các ý chính được trình bày theo từng phần để bạn ôn tập nhanh hơn.</Typography.Text></div></div><div className="markdown-lite">{renderSummaryContent(summary.content)}</div><Button onClick={onGenerate} loading={generating}>Tạo lại</Button></div></Spin> }
function MindMapPanel({ data, loading, onGenerate }: { data?: MindMap; loading: boolean; onGenerate: () => void }) { if (!data) return <EmptyAi title="Biến tài liệu thành bản đồ" description="Nhìn thấy mối liên hệ giữa các ý tưởng bằng một mind map tương tác." action={onGenerate} loading={loading} />; const nodes: Node[] = data.nodes.map(node => ({ id: node.id, data: { label: <div className="flow-node"><b>{node.label}</b>{node.description && <small>{node.description}</small>}</div> }, position: { x: node.positionX, y: node.positionY }, sourcePosition: Position.Bottom, targetPosition: Position.Top })); const edges: Edge[] = data.nodes.filter(node => node.parentNodeId).map(node => ({ id: `${node.parentNodeId}-${node.id}`, source: node.parentNodeId!, target: node.id, animated: true })); return <Spin spinning={loading} tip="AI đang tạo mind map..."><div className="mindmap-wrap"><Typography.Title level={3}>{data.title}</Typography.Title><div className="mindmap-canvas"><ReactFlow nodes={nodes} edges={edges} fitView /></div></div></Spin> }
function FlashcardsPanel({ data, loading, onGenerate }: { data?: Flashcards; loading: boolean; onGenerate: () => void }) { const [index, setIndex] = useState(0); const [flipped, setFlipped] = useState(false); if (!data) return <EmptyAi title="Ôn tập chủ động" description="Tạo flashcard từ những điểm quan trọng nhất trong tài liệu." action={onGenerate} loading={loading} />; const card = data.items[index]; const review = async (status: string) => { try { await api.post(`/flashcards/${card.id}/review`, { status }); message.success(status === 'known' ? 'Đã ghi nhận: bạn đã nhớ' : 'Đã ghi nhận: cần ôn lại') } catch (error) { message.error(errorMessage(error)) } }; return <Spin spinning={loading} tip="AI đang tạo flashcards..."><div className="flashcards-panel"><Typography.Title level={3}>Flashcards <Tag>{index + 1} / {data.items.length}</Tag></Typography.Title><div className="flashcard" onClick={() => setFlipped(value => !value)}><Typography.Text className="eyebrow">{flipped ? 'ANSWER' : 'QUESTION'}</Typography.Text><Typography.Title level={2}>{flipped ? card.answer : card.question}</Typography.Title>{flipped && card.explanation && <Typography.Paragraph>{card.explanation}</Typography.Paragraph>}<Typography.Text type="secondary">Nhấn để lật thẻ</Typography.Text></div><Space wrap><Button danger onClick={() => void review('unknown')}>Chưa nhớ</Button><Button onClick={() => void review('review')}>Ôn lại</Button><Button type="primary" onClick={() => void review('known')}>Đã nhớ</Button></Space><Space><Button disabled={index === 0} onClick={() => { setIndex(value => value - 1); setFlipped(false) }}>← Trước</Button><Button type="primary" disabled={index === data.items.length - 1} onClick={() => { setIndex(value => value + 1); setFlipped(false) }}>Tiếp →</Button></Space></div></Spin> }
function QuizPanel({ data, isPlus, loading, onGenerate }: { data?: Quiz; isPlus: boolean; loading: boolean; onGenerate: (questionCount: number) => void }) {
  const [answers, setAnswers] = useState<Record<string, string>>({})
  const [result, setResult] = useState<QuizResult>()
  const [submitError, setSubmitError] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [questionCount, setQuestionCount] = useState(5)
  const submitted = Boolean(result)

  const submit = async () => {
    if (!data || submitting || submitted) return
    setSubmitError('')
    setSubmitting(true)
    try {
      const response = await api.post<QuizResult>(`/quizzes/${data.id}/submit`, { answers: Object.entries(answers).map(([questionId, selectedOptionId]) => ({ questionId, selectedOptionId })) })
      setResult(response.data)
      message.success(`Bạn đạt ${response.data.score}/${response.data.totalQuestions} câu`)
    } catch (error) {
      const detail = errorMessage(error)
      setSubmitError(detail)
      message.error(detail)
    } finally { setSubmitting(false) }
  }

  const generate = () => { setResult(undefined); setSubmitError(''); setAnswers({}); onGenerate(questionCount) }
  if (!data) return <div className="quiz-panel quiz-empty"><Typography.Title level={3}>Tạo Quiz theo mục tiêu</Typography.Title><Typography.Paragraph type="secondary">Chọn số câu hỏi trước khi AI tạo bài kiểm tra.</Typography.Paragraph><QuizCountSelector isPlus={isPlus} value={questionCount} onChange={setQuestionCount} /><Button type="primary" loading={loading} onClick={generate}>Tạo Quiz</Button></div>

  return <Spin spinning={loading} tip="AI đang tạo quiz..."><div className="quiz-panel"><div className="quiz-toolbar"><div><Typography.Title level={3}>{data.title}</Typography.Title><Typography.Text type="secondary">{data.questions.length} câu hỏi · Câu chưa chọn sẽ được tính là sai.</Typography.Text></div><Space direction="vertical" align="end"><QuizCountSelector isPlus={isPlus} value={questionCount} onChange={setQuestionCount} /><Button onClick={generate} loading={loading}>Tạo lại theo số câu</Button></Space></div>{data.questions.map((question, index) => <Card key={question.id} className={`quiz-question ${submitted ? 'is-submitted' : ''}`}><Typography.Text strong>Câu {index + 1}</Typography.Text><Typography.Paragraph>{question.content}</Typography.Paragraph><Radio.Group value={answers[question.id]} disabled={submitted} onChange={event => { setAnswers({ ...answers, [question.id]: event.target.value }); setSubmitError('') }}>{question.options.map(option => <Radio key={option.id} value={option.id}><span className={`quiz-option ${submitted && option.isCorrect ? 'is-correct' : submitted && answers[question.id] === option.id ? 'is-wrong' : ''}`}>{option.text}{submitted && option.isCorrect && <CheckCircleOutlined className="quiz-answer-icon" />}{submitted && !option.isCorrect && answers[question.id] === option.id && <CloseCircleOutlined className="quiz-answer-icon" />}</span></Radio>)}</Radio.Group></Card>)}<Space wrap><Button htmlType="button" type="primary" loading={submitting} disabled={loading || submitted} onClick={submit}>{submitted ? 'Đã nộp bài' : 'Nộp bài'}</Button>{submitted && <Tag color="green">Đáp án đã khóa</Tag>}{result && <Card className="quiz-result"><Progress type="circle" percent={result.percentage} size={92} /><div><Typography.Title level={4}>Kết quả của bạn</Typography.Title><Typography.Text>{result.score}/{result.totalQuestions} câu đúng · {result.percentage}%</Typography.Text></div></Card>}</Space>{submitError && <Alert className="quiz-submit-error" type="error" showIcon message={submitError} />}</div></Spin>
}
function QuizCountSelector({ isPlus, value, onChange }: { isPlus: boolean; value: number; onChange: (value: number) => void }) { return <div className="quiz-count-selector"><Typography.Text strong>Số câu hỏi</Typography.Text><Radio.Group value={value} onChange={event => onChange(event.target.value)} optionType="button" buttonStyle="solid"><Radio.Button value={5}>5 · Free</Radio.Button><Radio.Button value={10}>10 · Free</Radio.Button><Radio.Button value={20} disabled={!isPlus}>20 · Plus</Radio.Button></Radio.Group>{!isPlus && <Typography.Text type="secondary">Nâng cấp Plus để mở khóa quiz 20 câu.</Typography.Text>}</div> }
function AnimatedChatMessage({ item }: { item: ChatMessage }) { const assistant = item.role !== 'user'; const [visible, setVisible] = useState(assistant ? '' : item.content); const [typing, setTyping] = useState(assistant); useEffect(() => { if (!assistant) { setVisible(item.content); setTyping(false); return } let cursor = 0; setVisible(''); setTyping(true); const timer = window.setInterval(() => { cursor = Math.min(item.content.length, cursor + Math.max(1, Math.ceil(item.content.length / 120))); setVisible(item.content.slice(0, cursor)); if (cursor >= item.content.length) { window.clearInterval(timer); setTyping(false) } }, 18); return () => window.clearInterval(timer) }, [assistant, item.content, item.id]); return <div className={`chat-message ${assistant ? 'assistant' : 'user'}`}><Avatar>{assistant ? <RobotOutlined /> : 'U'}</Avatar><div><Typography.Text strong>{assistant ? 'EduMind AI' : 'Bạn'}</Typography.Text><p>{visible}{typing && <span className="typing-cursor">▌</span>}</p></div></div> }
function ChatPanel({ messages, value, sending, onChange, onSend }: { messages: ChatMessage[]; value: string; sending: boolean; onChange: (value: string) => void; onSend: () => void }) { return <div className="chat-panel"><div className="chat-messages">{messages.length === 0 ? <Empty description="Đặt câu hỏi về nội dung tài liệu" /> : messages.map(item => <AnimatedChatMessage key={item.id} item={item} />)}{sending && <div className="chat-thinking"><Spin size="small" /> EduMind AI đang suy nghĩ...</div>}</div><Input.TextArea disabled={sending} value={value} onChange={event => onChange(event.target.value)} onPressEnter={event => { if (!event.shiftKey) { event.preventDefault(); onSend() } }} placeholder="Hỏi AI về tài liệu này..." autoSize={{ minRows: 2, maxRows: 5 }} /><Button type="primary" loading={sending} onClick={onSend} className="chat-send">Gửi câu hỏi</Button></div> }

function VerifyPendingPage() {
  const email = new URLSearchParams(window.location.search).get('email')
  return <div className="auth-page verify-page"><div className="auth-form-wrap"><div className="auth-form verify-card"><Typography.Text className="eyebrow">CHECK YOUR INBOX</Typography.Text><Typography.Title level={2}>Xác nhận email của bạn</Typography.Title><Typography.Paragraph type="secondary">Chúng tôi đã gửi liên kết xác nhận đến <b>{email}</b>. Hãy click vào liên kết trong Gmail trước khi đăng nhập.</Typography.Paragraph><div className="auth-switch"><Link to="/login">Quay lại đăng nhập</Link></div></div></div></div>
}

function VerifyEmailPage() {
  const [state, setState] = useState<'loading' | 'success' | 'error'>('loading')
  const [detail, setDetail] = useState('Đang xác nhận liên kết email của bạn...')
  useEffect(() => {
    const token = new URLSearchParams(window.location.search).get('token')
    if (!token) { setState('error'); setDetail('Liên kết xác nhận không hợp lệ.'); return }
    api.get('/auth/verify-email', { params: { token } }).then(() => { setState('success'); setDetail('Email đã được xác nhận. Bạn có thể đăng nhập ngay bây giờ.') }).catch(error => { setState('error'); setDetail(errorMessage(error)) })
  }, [])
  return <div className="auth-page verify-page"><div className="auth-form-wrap"><div className="auth-form verify-card"><Typography.Text className="eyebrow">EMAIL VERIFICATION</Typography.Text><Typography.Title level={2}>{state === 'loading' ? 'Đang xác nhận...' : state === 'success' ? 'Xác nhận thành công' : 'Không thể xác nhận'}</Typography.Title><Typography.Paragraph type="secondary">{detail}</Typography.Paragraph>{state !== 'loading' && <Link to={state === 'success' ? '/login' : '/register'}><Button type="primary" block>{state === 'success' ? 'Đăng nhập' : 'Tạo liên kết mới'}</Button></Link>}</div></div></div>
}

export default function App() { return <Routes><Route path="/login" element={<AuthPage mode="login" />} /><Route path="/register" element={<AuthPage mode="register" />} /><Route path="/verify-pending" element={<VerifyPendingPage />} /><Route path="/verify-email" element={<VerifyEmailPage />} /><Route path="*" element={<Protected><AppShell /></Protected>} /></Routes> }
